# Create a function to interpolate the velocity field at a given point
# and return all three velocity components: u = (ux, uy, uz)
function interpolated_vector_field(point::Point3f)
    ranges = (x_range, y_range, z_range)
    return Point3f(
        interpolated_getindex(ux_3d, ranges, point),
        interpolated_getindex(uy_3d, ranges, point),
        interpolated_getindex(uz_3d, ranges, point)
    )
end
